from collections import defaultdict

def expected_time_to_exit(N, M, paths):
    # Create adjacency list for the graph
    graph = defaultdict(list)
    for K, L in paths:
        graph[K].append(L)
        graph[L].append(K)

    # Initialize the expected time matrix
    E = [[0] * N for _ in range(N)]

    # Calculate expected times using dynamic programming
    for i in range(N):
        for j in range(N):
            if i != j:
                E[i][j] = float('inf')

    # Base case: E[i][i] = 0 for all i
    for i in range(N):
        E[i][i] = 0

    # Calculate expected times
    for _ in range(N - 1):
        for i in range(N):
            for j in range(N):
                if i != j:
                    # Calculate the expected time from i to j
                    E[i][j] = 1 + sum(E[i][k] for k in graph[i] if k != j) / len(graph[i])

    # The expected time to exit from clearing 0 is E[0][N-1]
    return E[0][N-1]

def main():
