import sys
from fractions import Fraction

def matrix_inverse(matrix):
    n = len(matrix)
    identity = [[Fraction(1 if i == j else 0) for j in range(n)] for i in range(n)]
    for i in range(n):
        if matrix[i][i] == 0:
            for j in range(i + 1, n):
                if matrix[j][i] != 0:
                    matrix[i], matrix[j] = matrix[j], matrix[i]
                    identity[i], identity[j] = identity[j], identity[i]
                    break
        assert matrix[i][i] != 0, "Matrix is not invertible"
        pivot = matrix[i][i]
        for j in range(n):
            matrix[i][j] /= pivot
            identity[i][j] /= pivot
        for k in range(n):
            if k != i:
                factor = matrix[k][i]
                for j in range(n):
                    matrix[k][j] -= factor * matrix[i][j]
                    identity[k][j] -= factor * identity[i][j]
    return identity

def expected_time_to_exit(N, M, paths):
    adjacency_matrix = [[0] * N for _ in range(N)]
    for K, L in paths:
        adjacency_matrix[K][L] = 1
        adjacency_matrix[L][K] = 1

    Q = []
    R = []
    for i in range(N - 1):
        row = []
        for j in range(N):
            if i != j and adjacency_matrix[i][j] == 1:
                row.append(Fraction(1, sum(adjacency_matrix[j])))
        if row:
            Q.append(row)
            R.append([Fraction(1 if i == N - 1 else 0)])
        else:
            Q.append([Fraction(0)])
            R.append([Fraction(1 if i == N - 1 else 0)])

    NQ = len(Q)
    I = [[Fraction(1 if i == j else 0) for j in range(NQ)] for i in range(NQ)]
    for i in range(NQ):
        for j in range(NQ):
            I[i][j] -= Q[i][j]

    inverse_I = matrix_inverse(I)
    B = [[0] * N for _ in range(N)]
    for i in range(NQ):
        for j in range(N):
            B[j][0] += sum(inverse_I[i][k] * R[k][0] for k in range(NQ))

    return float(B[0][0])

